function bindAigcFeatureTabs(){
 const root=$('#revision-service');ensureAigcStyle(root.ownerDocument);const heading=root.querySelector('.revision-entry-heading'),tabs=root.ownerDocument.createElement('nav');tabs.className='aigc-feature-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','表达优化与文本鉴别');tabs.innerHTML=`<button type="button" role="tab" id="aigc-expression-tab" aria-controls="aigc-expression-panel" aria-selected="true" data-aigc-feature="expression">${icon('pen',17)}表达优化</button><button type="button" role="tab" id="aigc-detection-tab" aria-controls="aigc-detection-panel" aria-selected="false" tabindex="-1" data-aigc-feature="detection">${icon('shield',17)}AI 文本鉴别</button>`;
 const expression=root.ownerDocument.createElement('div');expression.id='aigc-expression-panel';expression.setAttribute('role','tabpanel');expression.setAttribute('aria-labelledby','aigc-expression-tab');let node=heading;while(node){const next=node.nextSibling;expression.append(node);node=next;}root.append(tabs,expression);const detection=root.ownerDocument.createElement('section');detection.id='aigc-detection-panel';detection.hidden=true;detection.setAttribute('role','tabpanel');detection.setAttribute('aria-labelledby','aigc-detection-tab');root.append(detection);
 const choose=button=>withStableView(root,()=>{const selected=button.dataset.aigcFeature;updateToolBannerWorkflow(root.querySelector('header.tool-banner'),selected==='detection'?'aigc:detection':'aigc');for(const tab of tabs.querySelectorAll('button')){const active=tab===button;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;}expression.hidden=selected!=='expression';detection.hidden=selected!=='detection';if(selected==='detection'&&!aigcDetection)aigcDetection=mountAigcDetection({container:detection});});tabs.querySelectorAll('button').forEach(button=>{button.onclick=()=>choose(button);button.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const buttons=[...tabs.querySelectorAll('button')],next=event.key==='Home'?buttons[0]:event.key==='End'?buttons.at(-1):buttons[1-buttons.indexOf(button)];choose(next);next.focus({preventScroll:true});};});if(new URLSearchParams((window.location.hash.split('?')[1]||'')).get('view')==='detection')choose(tabs.querySelector('[data-aigc-feature="detection"]'));
}
