  const originalText=textArea.value,revision=bodyRevision,abort=new AbortController();parseController=abort;const stop=()=>abort.abort();viewController?.signal.addEventListener('abort',stop,{once:true});
  const owns=()=>active()&&location.hash===route&&request===generation&&fileInput.files[0]===file;
