    const use=form.ownerDocument.createElement('button');use.type='button';use.className='btn secondary';use.dataset.revUseParsed='';use.textContent='采用解析正文（替换当前正文）';use.onclick=()=>{if(owns())adopt(result,file);};status.append(use);saveCreateDraft();
